mapper.select:
select urs.* from uom_rating_scale urs
                      join gl_account ga on ga.default_uom_id = urs.uom_id
where ga.gl_account_id = #{glAccountId}
  and (urs.uom_id, urs.uom_rating_value) not in (
    select gamrs.uom_id, gamrs.uom_rating_value from gl_account_meas_rat_sc gamrs
    where gamrs.gl_account_id = #{glAccountId}
)
order by urs.uom_rating_value
